-- ---------------------------------------------------------------------
-- 6. Payment status, pay-later orders, payments counted in the shift that took them
-- ---------------------------------------------------------------------
do $$
begin
  if not exists (select 1 from pg_type where typname = 'payment_status') then
    create type public.payment_status as enum ('paid', 'partial', 'unpaid');
  end if;
end;
$$;
alter table public.orders add column if not exists payment_status public.payment_status not null default 'paid';
alter table public.orders add column if not exists paid_amount numeric(12, 2) not null default 0;
grant select (payment_status, paid_amount) on public.orders to authenticated;
alter table public.payments add column if not exists shift_id uuid references public.cash_shifts (id) on delete set null;
create index if not exists payments_shift_idx on public.payments (shift_id);
update public.payments p set shift_id = o.shift_id from public.orders o where o.id = p.order_id and p.shift_id is null;

create or replace function public.payments_set_shift()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.shift_id is null then
    select id into new.shift_id from public.cash_shifts where cashier_id = auth.uid() and closed_at is null;
    if new.shift_id is null then
      select shift_id into new.shift_id from public.orders where id = new.order_id;
    end if;
  end if;
  return new;
end;
$$;
drop trigger if exists payments_shift on public.payments;
create trigger payments_shift before insert on public.payments for each row execute function public.payments_set_shift();

create or replace function public.refresh_payment_status(p_order_id uuid)
returns void
language sql
security definer
set search_path = public
as $$
  update public.orders o set
    paid_amount = x.paid,
    payment_status = case
      when x.paid >= o.total - 0.009 then 'paid'::public.payment_status
      when x.paid > 0 then 'partial'::public.payment_status
      else 'unpaid'::public.payment_status end
  from (select coalesce(sum(amount), 0) paid from public.payments where order_id = p_order_id) x
  where o.id = p_order_id
    and (o.paid_amount is distinct from x.paid or o.payment_status is distinct from (case
      when x.paid >= o.total - 0.009 then 'paid'::public.payment_status
      when x.paid > 0 then 'partial'::public.payment_status
      else 'unpaid'::public.payment_status end))
$$;

create or replace function public.payments_status_trigger()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  perform public.refresh_payment_status(coalesce(new.order_id, old.order_id));
  return null;
end;
$$;
drop trigger if exists payments_status on public.payments;
create trigger payments_status after insert or update or delete on public.payments
for each row execute function public.payments_status_trigger();

create or replace function public.orders_status_trigger()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  perform public.refresh_payment_status(new.id);
  return null;
end;
$$;
drop trigger if exists orders_payment_status on public.orders;
create trigger orders_payment_status after insert or update of total on public.orders
for each row execute function public.orders_status_trigger();

update public.orders o set paid_amount = coalesce((select sum(amount) from public.payments where order_id = o.id), 0);
update public.orders set payment_status = case
  when paid_amount >= total - 0.009 then 'paid'::public.payment_status
  when paid_amount > 0 then 'partial'::public.payment_status
  else 'unpaid'::public.payment_status end;

-- place_order: extras priced from the database; pay_later lets payments be partial or empty
do $$
declare
  def text;
begin
  def := pg_get_functiondef('public.place_order(jsonb)'::regprocedure);
  -- extras
  def := replace(def, $r$    v_unit_cost := public.menu_item_cost(v_menu.id);
    v_subtotal := v_subtotal + v_menu.price * v_qty;$r$, $r$    v_unit_cost := public.menu_item_cost(v_menu.id);
    select coalesce(jsonb_agg(jsonb_build_object('id', o.id, 'name', o.name_ar, 'name_he', o.name_he, 'price', o.price) order by o.sort_order, o.name_ar), '[]'::jsonb),
           coalesce(sum(o.price), 0)
      into v_opts, v_opts_price
    from public.menu_item_options o
    where o.menu_item_id = v_menu.id and o.is_active
      and o.id in (select (jsonb_array_elements_text(coalesce(v_item -> 'options', '[]'::jsonb)))::uuid);
    if jsonb_array_length(v_opts) <> jsonb_array_length(coalesce(v_item -> 'options', '[]'::jsonb)) then
      raise exception 'INVALID_OPTIONS' using errcode = '22023';
    end if;
    v_menu.price := v_menu.price + v_opts_price;
    v_subtotal := v_subtotal + v_menu.price * v_qty;$r$);
  def := replace(def, $r$      'notes', left(coalesce(v_item ->> 'notes', ''), 200)
    );$r$, $r$      'notes', left(coalesce(v_item ->> 'notes', ''), 200), 'options', v_opts
    );$r$);
  def := replace(def, $r$      quantity, line_total, notes, created_at
    ) values ($r$, $r$      quantity, line_total, notes, options, created_at
    ) values ($r$);
  def := replace(def, $r$(v_item ->> 'price')::numeric * (v_item ->> 'qty')::integer, v_item ->> 'notes', v_created$r$,
                      $r$(v_item ->> 'price')::numeric * (v_item ->> 'qty')::integer, v_item ->> 'notes', coalesce(v_item -> 'options', '[]'::jsonb), v_created$r$);
  def := replace(def, $r$  v_lines jsonb := '[]'::jsonb;$r$, $r$  v_lines jsonb := '[]'::jsonb;
  v_opts jsonb;
  v_opts_price numeric;$r$);
  -- pay later
  def := replace(def, $r$  if abs(v_pay_sum - v_total) > 0.01 then$r$,
    $r$  if coalesce((payload ->> 'pay_later')::boolean, false) then
    if v_pay_sum > v_total + 0.01 then
      raise exception 'PAYMENT_MISMATCH' using errcode = '22023';
    end if;
  elsif abs(v_pay_sum - v_total) > 0.01 then$r$);
  if position('v_opts_price' in def) = 0 or position('pay_later' in def) = 0 or position('options, created_at' in def) = 0 then
    raise exception 'place_order patch failed';
  end if;
  execute def;
end;
$$;

-- collect payment for an order that was sent unpaid
create or replace function public.add_payment(p_order_id uuid, p_payments jsonb)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_role public.app_role := public.require_role('owner', 'manager', 'cashier');
  v_order public.orders;
  v_pay jsonb;
  v_sum numeric := 0;
  v_amount numeric;
  v_tendered numeric;
  v_method public.payment_method;
begin
  select * into v_order from public.orders where id = p_order_id for update;
  if not found then raise exception 'NOT_FOUND' using errcode = 'P0002'; end if;
  if v_order.status in ('cancelled', 'refunded') then raise exception 'ORDER_CLOSED' using errcode = '22023'; end if;
  if v_role = 'cashier' then
    if not exists (select 1 from public.cash_shifts where cashier_id = auth.uid() and closed_at is null) then
      raise exception 'SHIFT_REQUIRED' using errcode = '22023';
    end if;
  end if;
  if jsonb_typeof(p_payments) <> 'array' or jsonb_array_length(p_payments) = 0 then
    raise exception 'INVALID_PAYMENTS' using errcode = '22023';
  end if;
  for v_pay in select * from jsonb_array_elements(p_payments) loop
    v_amount := round((v_pay ->> 'amount')::numeric, 2);
    if v_amount is null or v_amount <= 0 then raise exception 'INVALID_PAYMENTS' using errcode = '22023'; end if;
    v_sum := v_sum + v_amount;
  end loop;
  if v_sum > v_order.total - v_order.paid_amount + 0.01 then
    raise exception 'PAYMENT_MISMATCH' using errcode = '22023';
  end if;
  for v_pay in select * from jsonb_array_elements(p_payments) loop
    v_method := (v_pay ->> 'method')::public.payment_method;
    v_amount := round((v_pay ->> 'amount')::numeric, 2);
    v_tendered := nullif(v_pay ->> 'tendered', '')::numeric;
    if v_method = 'cash' and v_tendered is not null and v_tendered < v_amount then
      raise exception 'INSUFFICIENT_CASH' using errcode = '22023';
    end if;
    insert into public.payments (order_id, method, amount, tendered, change_given)
    values (p_order_id, v_method, v_amount,
      case when v_method = 'cash' then coalesce(v_tendered, v_amount) end,
      case when v_method = 'cash' then greatest(coalesce(v_tendered, v_amount) - v_amount, 0) else 0 end);
  end loop;
  perform public.write_audit('add_payment', 'order', p_order_id, jsonb_build_object('order_number', v_order.order_number, 'amount', v_sum));
  return public.order_json(p_order_id);
end;
$$;

-- edits on an unpaid order must not create refunds
create or replace function public.recalc_order(p_order_id uuid)
returns numeric
language plpgsql
security definer
set search_path = public
as $$
declare
  v_order public.orders;
  v_sub numeric;
  v_cost numeric;
  v_disc numeric;
  v_total numeric;
  v_vat numeric;
  v_paid numeric;
  v_delta numeric := 0;
  v_was_paid boolean;
  v_method public.payment_method;
begin
  select * into v_order from public.orders where id = p_order_id for update;
  select coalesce(sum(amount), 0) into v_paid from public.payments where order_id = p_order_id;
  v_was_paid := v_paid >= v_order.total - 0.009;
  select coalesce(sum(line_total), 0), coalesce(sum(unit_cost_snapshot * quantity), 0)
    into v_sub, v_cost
  from public.order_items where order_id = p_order_id and voided_at is null;
  v_disc := case v_order.discount_type
    when 'percent' then round(v_sub * v_order.discount_value / 100, 2)
    when 'fixed' then least(v_order.discount_value, v_sub)
    else 0 end;
  v_total := v_sub - v_disc;
  select vat_percent into v_vat from public.restaurant_settings limit 1;
  update public.orders set
    subtotal = v_sub, discount_amount = v_disc, total = v_total,
    vat_amount = round(v_total * coalesce(v_vat, 0) / (100 + coalesce(v_vat, 0)), 2), cost_total = round(v_cost, 2)
  where id = p_order_id;

  if v_was_paid then
    v_delta := round(v_total - v_paid, 2);           -- paid orders: refund or charge the difference
  elsif v_paid > v_total + 0.009 then
    v_delta := round(v_total - v_paid, 2);           -- part-paid orders: refund only what was overpaid
  end if;
  if abs(v_delta) >= 0.01 then
    select method into v_method from public.payments where order_id = p_order_id and amount > 0
    order by (method = 'cash') desc, amount desc limit 1;
    insert into public.payments (order_id, method, amount, tendered, change_given)
    values (p_order_id, coalesce(v_method, 'cash'), v_delta, null, 0);
  end if;
  return v_delta;
end;
$$;
revoke execute on function public.recalc_order(uuid) from public, anon, authenticated;

-- ---------------------------------------------------------------------
-- 7. Salary advances (from the cashier drawer, deducted in payroll)
-- ---------------------------------------------------------------------
create table if not exists public.salary_advances (
  id uuid primary key default gen_random_uuid(),
  employee_id uuid not null references public.employees_meta (id) on delete cascade,
  amount numeric(12, 2) not null check (amount > 0),
  note text not null default '' check (char_length(note) <= 200),
  shift_id uuid references public.cash_shifts (id) on delete set null,
  created_by uuid references public.profiles (id) on delete set null,
  created_at timestamptz not null default now()
);
create index if not exists salary_advances_emp_idx on public.salary_advances (employee_id, created_at);
alter table public.salary_advances enable row level security;
drop policy if exists salary_advances_select on public.salary_advances;
create policy salary_advances_select on public.salary_advances for select to authenticated
  using (public.has_perm('employees')
    or exists (select 1 from public.employees_meta e where e.id = employee_id and e.profile_id = auth.uid()));

create or replace function public.record_advance(p_employee_id uuid, p_amount numeric, p_note text default '')
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  v_role public.app_role := public.require_role('owner', 'manager', 'cashier');
  v_shift uuid;
  v_id uuid;
  v_name text;
begin
  if p_amount is null or p_amount <= 0 or p_amount > 100000 then
    raise exception 'INVALID_AMOUNT' using errcode = '22023';
  end if;
  select full_name into v_name from public.employees_meta where id = p_employee_id and is_active;
  if v_name is null then raise exception 'NOT_FOUND' using errcode = 'P0002'; end if;
  select id into v_shift from public.cash_shifts where cashier_id = auth.uid() and closed_at is null;
  if v_shift is null and v_role = 'cashier' then
    raise exception 'SHIFT_REQUIRED' using errcode = '22023';
  end if;
  insert into public.salary_advances (employee_id, amount, note, shift_id, created_by)
  values (p_employee_id, round(p_amount, 2), left(coalesce(p_note, ''), 200), v_shift, auth.uid())
  returning id into v_id;
  perform public.write_audit('record_advance', 'salary_advance', v_id, jsonb_build_object('label', v_name, 'amount', round(p_amount, 2)));
  return v_id;
end;
$$;

-- staff list for the advance picker and the attendance kiosk (names only)
create or replace function public.staff_board()
returns jsonb
language sql
stable
security definer
set search_path = public
as $$
  select coalesce(jsonb_agg(jsonb_build_object(
      'id', e.id, 'full_name', e.full_name, 'avatar_url', e.avatar_url, 'position', e.position,
      'open_since', (select a.clock_in from public.attendance a where a.employee_id = e.id and a.clock_out is null)
    ) order by e.full_name), '[]'::jsonb)
  from public.employees_meta e
  where e.is_active and public.current_user_role() is not null
$$;

-- attendance kiosk: any signed-in staff device can clock any active employee in/out
create or replace function public.kiosk_clock(p_employee_id uuid, p_action text)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v public.attendance;
begin
  if public.current_user_role() is null then raise exception 'NOT_AUTHENTICATED' using errcode = '42501'; end if;
  if not exists (select 1 from public.employees_meta where id = p_employee_id and is_active) then
    raise exception 'NOT_FOUND' using errcode = 'P0002';
  end if;
  if p_action = 'in' then
    if exists (select 1 from public.attendance where employee_id = p_employee_id and clock_out is null) then
      raise exception 'ALREADY_CLOCKED_IN' using errcode = '22023';
    end if;
    insert into public.attendance (employee_id) values (p_employee_id) returning * into v;
  elsif p_action = 'out' then
    update public.attendance set clock_out = now() where employee_id = p_employee_id and clock_out is null returning * into v;
    if v.id is null then raise exception 'NOT_CLOCKED_IN' using errcode = '22023'; end if;
  else
    raise exception 'INVALID_ACTION' using errcode = '22023';
  end if;
  return to_jsonb(v);
end;
$$;

-- shift money: payments taken in this shift, minus advances paid from the drawer
create or replace function public.shift_cash(p_shift_id uuid)
returns table (cash numeric, card numeric, change_given numeric, advances numeric)
language sql
stable
security definer
set search_path = public
as $$
  select
    coalesce(sum(p.amount) filter (where p.method = 'cash'), 0),
    coalesce(sum(p.amount) filter (where p.method = 'card'), 0),
    coalesce(sum(p.change_given), 0),
    (select coalesce(sum(amount), 0) from public.salary_advances where shift_id = p_shift_id)
  from public.payments p join public.orders o on o.id = p.order_id
  where p.shift_id = p_shift_id and o.status not in ('cancelled', 'refunded')
$$;
revoke execute on function public.shift_cash(uuid) from public, anon, authenticated;

create or replace function public.shift_report(p_shift_id uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v public.cash_shifts;
  m record;
begin
  perform public.require_role('owner', 'manager', 'cashier');
  select * into v from public.cash_shifts where id = p_shift_id;
  if not found then
    raise exception 'NOT_FOUND' using errcode = 'P0002';
  end if;
  if v.cashier_id <> auth.uid() and not public.is_manager() then
    raise exception 'FORBIDDEN' using errcode = '42501';
  end if;
  select * into m from public.shift_cash(p_shift_id);

  return jsonb_build_object(
    'shift', to_jsonb(v),
    'cashier_name', (select full_name from public.profiles where id = v.cashier_id),
    'cash_sales', m.cash,
    'card_sales', m.card,
    'advances', m.advances,
    'expected_cash', coalesce(v.expected_cash, v.opening_float + m.cash - m.advances),
    'unpaid_count', (select count(*) from public.orders where shift_id = p_shift_id and status not in ('cancelled', 'refunded') and payment_status <> 'paid'),
    'unpaid_total', (select coalesce(sum(total - paid_amount), 0) from public.orders where shift_id = p_shift_id and status not in ('cancelled', 'refunded') and payment_status <> 'paid'),
    'orders_count', (select count(*) from public.orders where shift_id = p_shift_id and status not in ('cancelled', 'refunded')),
    'voided_count', (select count(*) from public.orders where shift_id = p_shift_id and status in ('cancelled', 'refunded')),
    'voided_total', (select coalesce(sum(total), 0) from public.orders where shift_id = p_shift_id and status in ('cancelled', 'refunded')),
    'discount_total', (select coalesce(sum(discount_amount), 0) from public.orders where shift_id = p_shift_id and status not in ('cancelled', 'refunded')),
    'gross_total', (select coalesce(sum(total), 0) from public.orders where shift_id = p_shift_id and status not in ('cancelled', 'refunded')),
    'by_type', coalesce((
      select jsonb_agg(jsonb_build_object('type', type, 'orders', c, 'total', t))
      from (select type, count(*) c, sum(total) t from public.orders
            where shift_id = p_shift_id and status not in ('cancelled', 'refunded') group by type) s
    ), '[]'::jsonb)
  );
end;
$$;

create or replace function public.close_shift(p_counted_cash numeric, p_notes text default '')
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v public.cash_shifts;
  m record;
begin
  perform public.require_role('owner', 'manager', 'cashier');
  if p_counted_cash is null or p_counted_cash < 0 then
    raise exception 'INVALID_AMOUNT' using errcode = '22023';
  end if;
  select * into v from public.cash_shifts where cashier_id = auth.uid() and closed_at is null for update;
  if not found then
    raise exception 'NO_OPEN_SHIFT' using errcode = 'P0002';
  end if;
  select * into m from public.shift_cash(v.id);
  update public.cash_shifts set
    cash_sales = m.cash, card_sales = m.card, expected_cash = opening_float + m.cash - m.advances,
    counted_cash = round(p_counted_cash, 2), notes = left(coalesce(p_notes, ''), 500), closed_at = now()
  where id = v.id;
  perform public.write_audit('close_shift', 'cash_shift', v.id,
    jsonb_build_object('expected', v.opening_float + m.cash - m.advances, 'counted', p_counted_cash));
  return public.shift_report(v.id);
end;
$$;

create or replace function public.refresh_shift_totals(p_shift_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  m record;
begin
  select * into m from public.shift_cash(p_shift_id);
  update public.cash_shifts s set
    cash_sales = m.cash, card_sales = m.card, expected_cash = s.opening_float + m.cash - m.advances
  where s.id = p_shift_id and s.closed_at is not null;
end;
$$;
revoke execute on function public.refresh_shift_totals(uuid) from public, anon, authenticated;

-- ---------------------------------------------------------------------
-- 8. Daily wage + payroll cycle (default: 12th to 12th)
-- ---------------------------------------------------------------------
alter type public.salary_type add value if not exists 'daily';
alter table public.restaurant_settings add column if not exists payroll_cycle_day integer not null default 12
  check (payroll_cycle_day between 1 and 28);
alter table public.payroll add column if not exists days_worked integer not null default 0;

create or replace function public.payroll_range(p_month date)
returns table (start_at timestamptz, end_at timestamptz)
language sql
stable
security definer
set search_path = public
as $$
  select
    (date_trunc('month', p_month)::date + (s.payroll_cycle_day - 1))::timestamp at time zone public.restaurant_tz(),
    ((date_trunc('month', p_month) + interval '1 month')::date + (s.payroll_cycle_day - 1))::timestamp at time zone public.restaurant_tz()
  from public.restaurant_settings s limit 1
$$;

create or replace function public.compute_payroll(p_month date)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  v_month date := date_trunc('month', p_month)::date;
  v_start timestamptz;
  v_end timestamptz;
  v_emp record;
  v_hours numeric;
  v_days integer;
  v_adv numeric;
  v_base numeric;
  v_n integer := 0;
begin
  perform public.require_perm('employees');
  select start_at, end_at into v_start, v_end from public.payroll_range(v_month);
  for v_emp in select * from public.employees_meta where is_active loop
    select coalesce(sum(extract(epoch from (clock_out - clock_in)) / 3600), 0),
           count(distinct (clock_in at time zone public.restaurant_tz())::date)
      into v_hours, v_days
    from public.attendance
    where employee_id = v_emp.id and clock_in >= v_start and clock_in < v_end
      and (clock_out is not null or v_emp.salary_type::text = 'daily');
    select coalesce(sum(amount), 0) into v_adv
    from public.salary_advances where employee_id = v_emp.id and created_at >= v_start and created_at < v_end;
    v_base := case v_emp.salary_type::text
      when 'hourly' then round(v_hours * v_emp.salary_amount, 2)
      when 'daily' then round(v_days * v_emp.salary_amount, 2)
      else v_emp.salary_amount end;
    insert into public.payroll (employee_id, period_month, hours_worked, days_worked, base_amount, advances)
    values (v_emp.id, v_month, round(v_hours, 2), v_days, v_base, v_adv)
    on conflict (employee_id, period_month) do update
      set hours_worked = excluded.hours_worked, days_worked = excluded.days_worked,
          base_amount = excluded.base_amount, advances = excluded.advances
      where public.payroll.status = 'draft';
    v_n := v_n + 1;
  end loop;
  return v_n;
end;
$$;

-- ---------------------------------------------------------------------
-- 9. Printers and routing (kitchen station per category / item)
-- ---------------------------------------------------------------------
create table if not exists public.printers (
  id uuid primary key default gen_random_uuid(),
  name text not null check (char_length(name) between 1 and 60),
  kind text not null default 'kitchen' check (kind in ('kitchen', 'receipt')),
  connection text not null default 'wifi' check (connection in ('wifi', 'bluetooth', 'usb')),
  address text not null default '' check (char_length(address) <= 120),
  paper_width integer not null default 80 check (paper_width in (58, 80)),
  is_active boolean not null default true,
  sort_order integer not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
alter table public.printers enable row level security;
drop trigger if exists printers_updated_at on public.printers;
create trigger printers_updated_at before update on public.printers for each row execute function public.set_updated_at();
drop policy if exists printers_select on public.printers;
create policy printers_select on public.printers for select to authenticated using (public.current_user_role() is not null);
drop policy if exists printers_write on public.printers;
create policy printers_write on public.printers for all to authenticated
  using (public.has_role('owner')) with check (public.has_role('owner'));
alter table public.restaurant_settings add column if not exists print_kitchen_on_send boolean not null default true;
alter table public.categories add column if not exists printer_id uuid references public.printers (id) on delete set null;
alter table public.menu_items add column if not exists printer_id uuid references public.printers (id) on delete set null;
grant select (printer_id) on public.menu_items to authenticated;

-- ---------------------------------------------------------------------
-- 10. delete_record: permission checks + customers and advances
-- ---------------------------------------------------------------------
do $$
declare
  def text;
begin
  def := pg_get_functiondef('public.delete_record(text, uuid, boolean)'::regprocedure);
  def := replace(def, $r$  case p_entity
  -- ---------------------------------------------------------------- order$r$, $r$  if p_entity in ('employee', 'attendance', 'payroll', 'work_shift', 'advance') then
    perform public.require_perm('employees');
  elsif p_entity = 'expense' then
    perform public.require_perm('reports');
  elsif p_entity = 'customer' then
    perform public.require_perm('customers');
  end if;

  case p_entity
  -- ---------------------------------------------------------------- order$r$);
  def := replace(def, $r$  when 'cash_shift' then$r$, $r$  when 'customer' then
    select count(*) into v_n from public.orders where customer_id = p_id;
    if v_n > 0 then v_fx := v_fx || jsonb_build_object('t', 'note', 'what', 'customer_orders_kept'); end if;
    if not p_dry_run then delete from public.customers where id = p_id; end if;

  when 'advance' then
    if exists (select 1 from public.salary_advances a join public.cash_shifts s on s.id = a.shift_id where a.id = p_id and s.closed_at is not null) then
      v_fx := v_fx || jsonb_build_object('t', 'note', 'what', 'shift_recalc');
    end if;
    if not p_dry_run then
      select shift_id into v_child from public.salary_advances where id = p_id;
      delete from public.salary_advances where id = p_id;
      if v_child is not null then perform public.refresh_shift_totals(v_child); end if;
    end if;

  when 'cash_shift' then$r$);
  if position($q$when 'customer'$q$ in def) = 0 or position('require_perm(''employees'')' in def) = 0 then
    raise exception 'delete_record patch failed';
  end if;
  execute def;
end;
$$;

-- ---------------------------------------------------------------------
-- 11. Activity log + realtime for the new tables
-- ---------------------------------------------------------------------
do $$
declare
  t text;
begin
  foreach t in array array['customers', 'menu_item_options', 'printers', 'user_permissions', 'salary_advances'] loop
    execute format('drop trigger if exists %I on public.%I', t || '_audit', t);
    if t <> 'salary_advances' then
      execute format('create trigger %I after insert or update or delete on public.%I for each row execute function public.audit_row()', t || '_audit', t);
    end if;
    if not exists (select 1 from pg_publication_tables where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = t) then
      execute format('alter publication supabase_realtime add table public.%I', t);
    end if;
  end loop;
end;
$$;

-- user_permissions has no id column: log it by user
create or replace function public.audit_permissions()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  r record := coalesce(new, old);
begin
  insert into public.audit_log (user_id, action, entity, entity_id, details)
  values (auth.uid(), lower(tg_op), 'user_permissions', r.user_id,
          jsonb_build_object('label', (select full_name from public.profiles where id = r.user_id),
                             'permission', r.permission, 'expires_at', r.expires_at));
  return null;
end;
$$;
drop trigger if exists user_permissions_audit on public.user_permissions;
create trigger user_permissions_audit after insert or update or delete on public.user_permissions
for each row execute function public.audit_permissions();

-- ---------------------------------------------------------------------
-- 12. Function grants
-- ---------------------------------------------------------------------
revoke execute on function public.grant_select_except(text, text[]), public.guard_cost_columns(),
  public.refresh_customer(uuid), public.orders_customer_sync(), public.orders_customer_totals(),
  public.payments_set_shift(), public.refresh_payment_status(uuid), public.payments_status_trigger(),
  public.orders_status_trigger(), public.audit_permissions(), public.menu_item_cost(uuid)
  from public, anon, authenticated;
grant execute on function public.has_perm(text), public.my_permissions(), public.cost_data(), public.po_item_costs(uuid),
  public.find_customers(text), public.add_payment(uuid, jsonb), public.record_advance(uuid, numeric, text),
  public.staff_board(), public.kiosk_clock(uuid, text), public.apply_stock_count(uuid), public.report_inventory(date, date)
  to authenticated;


-- >>> 20261113000012_bulk_delete_and_spec.sql
-- =====================================================================
-- Bulk delete (multi-select) + remaining spec items:
-- daily absence, manual goods receipt, inventory last update, analytics.
-- =====================================================================

-- ---------------------------------------------------------------------
-- 1. Delete many records of one kind at once — all or nothing.
--    Effects of each record are concatenated (the app merges them for display).
--    A record already removed by an earlier one in the same batch
--    (e.g. an item inside a deleted category) is skipped.
-- ---------------------------------------------------------------------
create or replace function public.delete_records(p_entity text, p_ids uuid[], p_dry_run boolean default true)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_id uuid;
  v_fx jsonb := '[]'::jsonb;
  v_one jsonb;
  v_done integer := 0;
begin
  if p_ids is null or cardinality(p_ids) = 0 then
    return jsonb_build_object('effects', '[]'::jsonb, 'count', 0);
  end if;
  if cardinality(p_ids) > 500 then
    raise exception 'TOO_MANY_ITEMS' using errcode = '22023';
  end if;
  foreach v_id in array p_ids loop
    begin
      v_one := public.delete_record(p_entity, v_id, p_dry_run);
      v_fx := v_fx || coalesce(v_one, '[]'::jsonb);
      v_done := v_done + 1;
    exception when sqlstate 'P0002' then
      null; -- already gone (deleted together with a parent in this batch)
    end;
  end loop;
  return jsonb_build_object('effects', v_fx, 'count', v_done);
end;
$$;
grant execute on function public.delete_records(text, uuid[], boolean) to authenticated;

-- ---------------------------------------------------------------------
-- 2. Daily workers: a day is recorded as present or absent
-- ---------------------------------------------------------------------
alter table public.attendance add column if not exists absent boolean not null default false;
grant select (absent) on public.attendance to authenticated;

create or replace function public.kiosk_absent(p_employee_id uuid, p_date date default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_day date := coalesce(p_date, (now() at time zone public.restaurant_tz())::date);
  v_start timestamptz := v_day::timestamp at time zone public.restaurant_tz();
  v public.attendance;
begin
  if public.current_user_role() is null then raise exception 'NOT_AUTHENTICATED' using errcode = '42501'; end if;
  if not exists (select 1 from public.employees_meta where id = p_employee_id and is_active) then
    raise exception 'NOT_FOUND' using errcode = 'P0002';
  end if;
  if exists (select 1 from public.attendance where employee_id = p_employee_id
             and clock_in >= v_start and clock_in < v_start + interval '1 day') then
    raise exception 'ALREADY_RECORDED' using errcode = '22023';
  end if;
  insert into public.attendance (employee_id, clock_in, clock_out, absent)
  values (p_employee_id, v_start, v_start + interval '1 minute', true)
  returning * into v;
  return to_jsonb(v);
end;
$$;
grant execute on function public.kiosk_absent(uuid, date) to authenticated;

-- payroll counts only days actually worked; absences carry no hours
do $$
declare
  def text;
begin
  def := pg_get_functiondef('public.compute_payroll(date)'::regprocedure);
  def := replace(def, $r$where employee_id = v_emp.id and clock_in >= v_start and clock_in < v_end
      and (clock_out is not null or v_emp.salary_type::text = 'daily');$r$,
    $r$where employee_id = v_emp.id and clock_in >= v_start and clock_in < v_end and not absent
      and (clock_out is not null or v_emp.salary_type::text = 'daily');$r$);
  if position('and not absent' in def) = 0 then raise exception 'compute_payroll patch failed'; end if;
  execute def;
end;
$$;

-- staff board also says whether a day was marked absent today
create or replace function public.staff_board()
returns jsonb
language sql
stable
security definer
set search_path = public
as $$
  select coalesce(jsonb_agg(jsonb_build_object(
      'id', e.id, 'full_name', e.full_name, 'avatar_url', e.avatar_url, 'position', e.position,
      'daily', e.salary_type::text = 'daily',
      'open_since', (select a.clock_in from public.attendance a where a.employee_id = e.id and a.clock_out is null and not a.absent),
      'absent_today', exists (select 1 from public.attendance a where a.employee_id = e.id and a.absent
        and a.clock_in >= (now() at time zone public.restaurant_tz())::date::timestamp at time zone public.restaurant_tz()),
      'present_today', exists (select 1 from public.attendance a where a.employee_id = e.id and not a.absent
        and a.clock_in >= (now() at time zone public.restaurant_tz())::date::timestamp at time zone public.restaurant_tz())
    ) order by e.full_name), '[]'::jsonb)
  from public.employees_meta e
  where e.is_active and public.current_user_role() is not null
$$;

-- ---------------------------------------------------------------------
-- 3. Manual goods receipt: material, quantity, date, supplier (price only for the owner)
-- ---------------------------------------------------------------------
create or replace function public.receive_goods(p_lines jsonb, p_supplier_id uuid, p_date date, p_notes text default '')
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  v_po uuid;
  v_line jsonb;
  v_cost numeric;
  v_costs boolean := public.has_perm('costs');
begin
  perform public.require_role('owner', 'manager', 'inventory', 'cashier');
  if jsonb_typeof(p_lines) <> 'array' or jsonb_array_length(p_lines) = 0 then
    raise exception 'EMPTY_ORDER' using errcode = '22023';
  end if;
  if p_supplier_id is null then
    raise exception 'SUPPLIER_REQUIRED' using errcode = '22023';
  end if;
  insert into public.purchase_orders (supplier_id, status, notes, expected_date, created_by)
  values (p_supplier_id, 'draft', left(coalesce(p_notes, ''), 500), coalesce(p_date, current_date), auth.uid())
  returning id into v_po;
  for v_line in select * from jsonb_array_elements(p_lines) loop
    if coalesce((v_line ->> 'quantity')::numeric, 0) <= 0 then
      raise exception 'INVALID_QUANTITY' using errcode = '22023';
    end if;
    -- staff never set prices: their lines take the material's current cost
    v_cost := case when v_costs and (v_line ->> 'unit_cost') is not null then greatest((v_line ->> 'unit_cost')::numeric, 0)
                   else (select cost_per_unit from public.ingredients where id = (v_line ->> 'ingredient_id')::uuid) end;
    insert into public.purchase_order_items (purchase_order_id, ingredient_id, quantity, unit_cost)
    values (v_po, (v_line ->> 'ingredient_id')::uuid, (v_line ->> 'quantity')::numeric, coalesce(v_cost, 0));
  end loop;
  perform public.receive_purchase_order(v_po);
  if p_date is not null and p_date <> (now() at time zone public.restaurant_tz())::date then
    update public.purchase_orders set received_at = (p_date::timestamp + interval '12 hours') at time zone public.restaurant_tz() where id = v_po;
  end if;
  return v_po;
end;
$$;
grant execute on function public.receive_goods(jsonb, uuid, date, text) to authenticated;

-- receive_purchase_order is called by staff through receive_goods; cashiers may receive too
do $$
declare
  def text;
begin
  def := pg_get_functiondef('public.receive_purchase_order(uuid)'::regprocedure);
  def := replace(def, $r$public.require_role('owner', 'manager', 'inventory')$r$, $r$public.require_role('owner', 'manager', 'inventory', 'cashier')$r$);
  execute def;
end;
$$;
drop policy if exists suppliers_select_cashier on public.suppliers;
create policy suppliers_select_cashier on public.suppliers for select to authenticated using (public.has_role('cashier'));

-- ---------------------------------------------------------------------
-- 4. Owner analytics assistant: consumption, repeated count differences,
--    materials likely to run out, and a daily report
-- ---------------------------------------------------------------------
create or replace function public.inventory_insights(p_days integer default 14)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_days integer := greatest(3, least(coalesce(p_days, 14), 90));
begin
  perform public.require_perm('reports');
  return jsonb_build_object(
    'days', v_days,
    -- average daily use from sales and waste, and how long the current stock lasts
    'forecast', coalesce((
      select jsonb_agg(x order by x.days_left nulls last, x.name)
      from (
        select i.id, i.name_ar as name, i.name_he, i.unit, i.quantity, i.min_quantity,
          round(u.used / v_days, 3) as per_day,
          case when u.used > 0 then round(greatest(i.quantity, 0) / (u.used / v_days), 1) end as days_left
        from public.ingredients i
        join (select ingredient_id, sum(-change) as used from public.stock_movements
              where reason in ('sale', 'waste') and change < 0 and created_at >= now() - make_interval(days => v_days)
              group by ingredient_id) u on u.ingredient_id = i.id
        where i.is_active
      ) x
    ), '[]'::jsonb),
    -- materials whose stocktakes keep coming out different from the books
    'repeated_variances', coalesce((
      select jsonb_agg(x order by x.times desc, abs(x.total) desc)
      from (
        select i.id, i.name_ar as name, i.name_he, i.unit, count(*) as times,
          round(sum(ci.counted_quantity - ci.expected_quantity), 3) as total
        from public.stock_count_items ci
        join public.stock_counts c on c.id = ci.stock_count_id and c.status = 'applied'
        join public.ingredients i on i.id = ci.ingredient_id
        where ci.counted_quantity is not null and abs(ci.counted_quantity - ci.expected_quantity) > 0.0005
          and c.applied_at >= now() - interval '120 days'
        group by i.id, i.name_ar, i.name_he, i.unit
        having count(*) >= 2
      ) x
    ), '[]'::jsonb),
    -- consumption expected from recipes vs. what actually left the shelf (sales + waste + count corrections)
    'consumption', coalesce((
      select jsonb_agg(x order by abs(x.gap) desc)
      from (
        select i.id, i.name_ar as name, i.name_he, i.unit,
          round(coalesce(sum(-m.change) filter (where m.reason = 'sale'), 0), 3) as by_recipe,
          round(coalesce(sum(-m.change) filter (where m.reason = 'waste'), 0), 3) as waste,
          round(coalesce(sum(-m.change) filter (where m.reason = 'adjustment'), 0), 3) as gap
        from public.stock_movements m join public.ingredients i on i.id = m.ingredient_id
        where m.created_at >= now() - make_interval(days => v_days)
        group by i.id, i.name_ar, i.name_he, i.unit
        having coalesce(sum(-m.change) filter (where m.reason in ('sale', 'waste', 'adjustment')), 0) <> 0
        order by abs(coalesce(sum(-m.change) filter (where m.reason = 'adjustment'), 0)) desc
        limit 15
      ) x
    ), '[]'::jsonb)
  );
end;
$$;
grant execute on function public.inventory_insights(integer) to authenticated;

create or replace function public.daily_report(p_date date default null)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_day date := coalesce(p_date, (now() at time zone public.restaurant_tz())::date);
  v_s timestamptz := v_day::timestamp at time zone public.restaurant_tz();
  v_e timestamptz := (v_day + 1)::timestamp at time zone public.restaurant_tz();
  v_avg numeric;
begin
  perform public.require_perm('reports');
  select coalesce(avg(t), 0) into v_avg from (
    select sum(total) t from public.orders
    where status not in ('cancelled', 'refunded') and created_at >= v_s - interval '28 days' and created_at < v_s
    group by public.local_date(created_at)) d;
  return jsonb_build_object(
    'date', v_day,
    'sales', (select coalesce(sum(total), 0) from public.orders where status not in ('cancelled', 'refunded') and created_at >= v_s and created_at < v_e),
    'orders', (select count(*) from public.orders where status not in ('cancelled', 'refunded') and created_at >= v_s and created_at < v_e),
    'avg_day_sales', round(v_avg, 2),
    'cancelled', (select count(*) from public.orders where status in ('cancelled', 'refunded') and created_at >= v_s and created_at < v_e),
    'unpaid', (select coalesce(sum(total - paid_amount), 0) from public.orders where status not in ('cancelled', 'refunded') and payment_status <> 'paid' and created_at >= v_s and created_at < v_e),
    'discounts', (select coalesce(sum(discount_amount), 0) from public.orders where status not in ('cancelled', 'refunded') and created_at >= v_s and created_at < v_e),
    'expenses', (select coalesce(sum(amount), 0) from public.expenses where expense_date = v_day),
    'cogs', case when public.has_perm('costs') then (select coalesce(sum(cost_total), 0) from public.orders where status not in ('cancelled', 'refunded') and created_at >= v_s and created_at < v_e) end,
    'top_items', coalesce((select jsonb_agg(x) from (
        select oi.name_snapshot as name, sum(oi.quantity) qty from public.order_items oi join public.orders o on o.id = oi.order_id
        where o.status not in ('cancelled', 'refunded') and oi.voided_at is null and o.created_at >= v_s and o.created_at < v_e
        group by oi.name_snapshot order by qty desc limit 5) x), '[]'::jsonb),
    'low_stock', coalesce((select jsonb_agg(jsonb_build_object('name', name_ar, 'quantity', quantity, 'unit', unit, 'min', min_quantity))
        from public.ingredients where is_active and quantity <= min_quantity), '[]'::jsonb),
    'staff', coalesce((select jsonb_agg(x) from (
        select e.full_name as name, round(sum(extract(epoch from (coalesce(a.clock_out, now()) - a.clock_in)) / 3600), 1) as hours
        from public.attendance a join public.employees_meta e on e.id = a.employee_id
        where not a.absent and a.clock_in >= v_s and a.clock_in < v_e group by e.full_name order by hours desc) x), '[]'::jsonb),
    'absent', coalesce((select jsonb_agg(e.full_name) from public.attendance a join public.employees_meta e on e.id = a.employee_id
        where a.absent and a.clock_in >= v_s and a.clock_in < v_e), '[]'::jsonb),
    'advances', (select coalesce(sum(amount), 0) from public.salary_advances where created_at >= v_s and created_at < v_e)
  );
end;
$$;
grant execute on function public.daily_report(date) to authenticated;

-- ---------------------------------------------------------------------
-- 5. Owner dashboard: expenses today and who is on shift
-- ---------------------------------------------------------------------
create or replace function public.dashboard_extra()
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_today date := (now() at time zone public.restaurant_tz())::date;
begin
  perform public.require_perm('reports');
  return jsonb_build_object(
    'expenses_today', (select coalesce(sum(amount), 0) from public.expenses where expense_date = v_today),
    'unpaid_orders', (select count(*) from public.orders where status not in ('cancelled', 'refunded') and payment_status <> 'paid'),
    'printers', (select count(*) from public.printers where is_active),
    'on_shift', coalesce((select jsonb_agg(jsonb_build_object('name', e.full_name, 'avatar_url', e.avatar_url, 'since', a.clock_in) order by a.clock_in)
        from public.attendance a join public.employees_meta e on e.id = a.employee_id
        where a.clock_out is null and not a.absent), '[]'::jsonb),
    'forgot_clock_out', (select count(*) from public.attendance where clock_out is null and not absent and clock_in < now() - interval '14 hours'),
    'activity', coalesce((select jsonb_agg(x) from (
        select l.action, l.entity, l.details, l.created_at, p.full_name as by
        from public.audit_log l left join public.profiles p on p.id = l.user_id
        order by l.created_at desc limit 8) x), '[]'::jsonb)
  );
end;
$$;
grant execute on function public.dashboard_extra() to authenticated;

-- ---------------------------------------------------------------------
-- 6. Report sections (period → figures). All need the 'reports' grant;
--    the staff section needs 'employees'.
-- ---------------------------------------------------------------------
create or replace function public.report_orders(p_from date, p_to date)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_s timestamptz := public.range_start(p_from);
  v_e timestamptz := public.range_end(p_to);
begin
  perform public.require_perm('reports');
  perform public.check_range(p_from, p_to);
  return jsonb_build_object(
    'by_status', coalesce((select jsonb_agg(jsonb_build_object('status', status, 'count', c, 'total', t))
      from (select status, count(*) c, sum(total) t from public.orders where created_at >= v_s and created_at < v_e group by status) x), '[]'::jsonb),
    'by_type', coalesce((select jsonb_agg(jsonb_build_object('type', type, 'count', c, 'total', t))
      from (select type, count(*) c, sum(total) t from public.orders where created_at >= v_s and created_at < v_e
            and status not in ('cancelled', 'refunded') group by type) x), '[]'::jsonb),
    'avg_ready_minutes', (select round(avg(extract(epoch from (ready_at - created_at)) / 60)::numeric, 1)
      from public.orders where created_at >= v_s and created_at < v_e and ready_at is not null),
    'cancelled', (select count(*) from public.orders where created_at >= v_s and created_at < v_e and status = 'cancelled'),
    'cancelled_total', (select coalesce(sum(total), 0) from public.orders where created_at >= v_s and created_at < v_e and status = 'cancelled'),
    'refunded', (select count(*) from public.orders where created_at >= v_s and created_at < v_e and status = 'refunded'),
    'refunded_total', (select coalesce(sum(total), 0) from public.orders where created_at >= v_s and created_at < v_e and status = 'refunded'),
    'voided_items', (select coalesce(sum(oi.quantity), 0) from public.order_items oi join public.orders o on o.id = oi.order_id
      where o.created_at >= v_s and o.created_at < v_e and oi.voided_at is not null),
    'voids', coalesce((select jsonb_agg(x order by x.at desc) from (
      select o.id, o.order_number, o.total, o.status, o.void_reason as reason, o.voided_at as at, p.full_name as by
      from public.orders o left join public.profiles p on p.id = o.voided_by
      where o.created_at >= v_s and o.created_at < v_e and o.status in ('cancelled', 'refunded')
      order by o.voided_at desc limit 200) x), '[]'::jsonb)
  );
end;
$$;

create or replace function public.report_payments(p_from date, p_to date)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_s timestamptz := public.range_start(p_from);
  v_e timestamptz := public.range_end(p_to);
begin
  perform public.require_perm('reports');
  perform public.check_range(p_from, p_to);
  return jsonb_build_object(
    'by_method', coalesce((select jsonb_agg(jsonb_build_object('method', method, 'amount', amt, 'count', c, 'refunds', r))
      from (select p.method, sum(p.amount) filter (where p.amount > 0) amt, count(*) filter (where p.amount > 0) c,
                   coalesce(-sum(p.amount) filter (where p.amount < 0), 0) r
            from public.payments p where p.created_at >= v_s and p.created_at < v_e group by p.method) x), '[]'::jsonb),
    'by_status', coalesce((select jsonb_agg(jsonb_build_object('status', payment_status, 'count', c, 'total', t, 'due', d))
      from (select payment_status, count(*) c, sum(total) t, sum(total - paid_amount) d from public.orders
            where created_at >= v_s and created_at < v_e and status not in ('cancelled', 'refunded') group by payment_status) x), '[]'::jsonb),
    'change_given', (select coalesce(sum(change_given), 0) from public.payments where created_at >= v_s and created_at < v_e),
    'unpaid', coalesce((select jsonb_agg(x order by x.created_at desc) from (
      select o.id, o.order_number, o.total, o.paid_amount, o.payment_status, o.customer_name, o.customer_phone, o.created_at
      from public.orders o where o.created_at >= v_s and o.created_at < v_e
        and o.status not in ('cancelled', 'refunded') and o.payment_status <> 'paid' limit 300) x), '[]'::jsonb)
  );
end;
$$;

create or replace function public.report_tax(p_from date, p_to date)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_s timestamptz := public.range_start(p_from);
  v_e timestamptz := public.range_end(p_to);
begin
  perform public.require_perm('reports');
  perform public.check_range(p_from, p_to);
  return jsonb_build_object(
    'rate', (select vat_percent from public.restaurant_settings limit 1),
    'gross', (select coalesce(sum(total), 0) from public.orders where created_at >= v_s and created_at < v_e and status not in ('cancelled', 'refunded')),
    'vat', (select coalesce(sum(vat_amount), 0) from public.orders where created_at >= v_s and created_at < v_e and status not in ('cancelled', 'refunded')),
    'by_day', coalesce((select jsonb_agg(jsonb_build_object('date', d, 'gross', g, 'vat', v, 'orders', c) order by d)
      from (select public.local_date(created_at) d, sum(total) g, sum(vat_amount) v, count(*) c from public.orders
            where created_at >= v_s and created_at < v_e and status not in ('cancelled', 'refunded') group by 1) x), '[]'::jsonb)
  );
end;
$$;

create or replace function public.report_purchases(p_from date, p_to date)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_s timestamptz := public.range_start(p_from);
  v_e timestamptz := public.range_end(p_to);
  v_costs boolean := public.has_perm('costs');
begin
  perform public.require_perm('reports');
  perform public.check_range(p_from, p_to);
  return jsonb_build_object(
    'costs_visible', v_costs,
    'by_supplier', coalesce((select jsonb_agg(x order by x.orders desc) from (
      select s.id, s.name, s.phone, count(po.id) as orders,
        count(po.id) filter (where po.status = 'received') as received,
        case when v_costs then coalesce(sum(po.total) filter (where po.status = 'received'), 0) end as total
      from public.suppliers s join public.purchase_orders po on po.supplier_id = s.id
      where po.created_at >= v_s and po.created_at < v_e
      group by s.id, s.name, s.phone) x), '[]'::jsonb),
    'orders', coalesce((select jsonb_agg(x order by x.created_at desc) from (
      select po.id, po.po_number, po.status, po.created_at, po.received_at, s.name as supplier,
        (select count(*) from public.purchase_order_items i where i.purchase_order_id = po.id) as lines,
        case when v_costs then po.total end as total
      from public.purchase_orders po left join public.suppliers s on s.id = po.supplier_id
      where po.created_at >= v_s and po.created_at < v_e limit 300) x), '[]'::jsonb),
    'materials', coalesce((select jsonb_agg(x order by x.quantity desc) from (
      select i.name_ar as name, i.unit, round(sum(pi.quantity), 3) as quantity,
        case when v_costs then round(sum(pi.quantity * pi.unit_cost), 2) end as total
      from public.purchase_order_items pi
      join public.purchase_orders po on po.id = pi.purchase_order_id and po.status = 'received'
      join public.ingredients i on i.id = pi.ingredient_id
      where po.received_at >= v_s and po.received_at < v_e
      group by i.name_ar, i.unit) x), '[]'::jsonb)
  );
end;
$$;

create or replace function public.report_cash(p_from date, p_to date)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_s timestamptz := public.range_start(p_from);
  v_e timestamptz := public.range_end(p_to);
begin
  perform public.require_perm('reports');
  perform public.check_range(p_from, p_to);
  return coalesce((select jsonb_agg(x order by x.opened_at desc) from (
    select s.id, s.opened_at, s.closed_at, s.opening_float, p.full_name as cashier,
      m.cash, m.card, m.advances,
      coalesce(s.expected_cash, s.opening_float + m.cash - m.advances) as expected,
      s.counted_cash as counted,
      case when s.counted_cash is not null then s.counted_cash - coalesce(s.expected_cash, s.opening_float + m.cash - m.advances) end as variance
    from public.cash_shifts s
    left join public.profiles p on p.id = s.cashier_id
    cross join lateral public.shift_cash(s.id) m
    where s.opened_at >= v_s and s.opened_at < v_e) x), '[]'::jsonb);
end;
$$;

create or replace function public.report_staff(p_from date, p_to date)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_s timestamptz := public.range_start(p_from);
  v_e timestamptz := public.range_end(p_to);
begin
  perform public.require_perm('employees');
  perform public.check_range(p_from, p_to);
  return jsonb_build_object(
    'employees', coalesce((select jsonb_agg(x order by x.name) from (
      select e.id, e.full_name as name, e.position, e.salary_type, e.salary_amount,
        coalesce(round(sum(extract(epoch from (coalesce(a.clock_out, now()) - a.clock_in)) / 3600) filter (where not a.absent)::numeric, 2), 0) as hours,
        count(distinct public.local_date(a.clock_in)) filter (where not a.absent) as days,
        count(*) filter (where a.absent) as absences,
        (select coalesce(sum(amount), 0) from public.salary_advances sa where sa.employee_id = e.id and sa.created_at >= v_s and sa.created_at < v_e) as advances,
        (select coalesce(sum(net_amount), 0) from public.payroll pr where pr.employee_id = e.id
           and pr.period_month between date_trunc('month', p_from)::date and date_trunc('month', p_to)::date) as payroll,
        (select coalesce(sum(net_amount), 0) from public.payroll pr where pr.employee_id = e.id and pr.status = 'paid'
           and pr.paid_at >= v_s and pr.paid_at < v_e) as paid
      from public.employees_meta e
      left join public.attendance a on a.employee_id = e.id and a.clock_in >= v_s and a.clock_in < v_e
      group by e.id) x), '[]'::jsonb),
    'advances', coalesce((select jsonb_agg(x order by x.created_at desc) from (
      select sa.id, sa.amount, sa.note, sa.created_at, e.full_name as employee, p.full_name as by
      from public.salary_advances sa join public.employees_meta e on e.id = sa.employee_id
      left join public.profiles p on p.id = sa.created_by
      where sa.created_at >= v_s and sa.created_at < v_e) x), '[]'::jsonb)
  );
end;
$$;

grant execute on function public.report_orders(date, date), public.report_payments(date, date), public.report_tax(date, date),
  public.report_purchases(date, date), public.report_cash(date, date), public.report_staff(date, date) to authenticated;


-- >>> 20261113000013_user_permissions_v2.sql
-- =====================================================================
-- Per-user permissions: every screen / action is a permission with a default
-- per role. The owner can switch any of them on or off for any account
-- (switching on can be temporary). Enforced here, not only in the app.
-- =====================================================================

alter table public.user_permissions add column if not exists effect text not null default 'grant'
  check (effect in ('grant', 'deny'));
alter table public.user_permissions drop constraint if exists user_permissions_permission_check;
alter table public.user_permissions add constraint user_permissions_permission_check check (permission in (
  'pos', 'kitchen', 'orders', 'customers', 'menu', 'inventory', 'stocktake', 'stocktake_approve', 'receive_goods',
  'costs', 'attendance', 'employees', 'advance', 'reports', 'activity'));

-- what each role gets unless the owner says otherwise
create or replace function public.role_defaults(p_role public.app_role)
returns text[]
language sql
immutable
as $$
  select case p_role
    when 'owner' then array['pos', 'kitchen', 'orders', 'customers', 'menu', 'inventory', 'stocktake', 'stocktake_approve',
                            'receive_goods', 'costs', 'attendance', 'employees', 'advance', 'reports', 'activity']
    when 'manager' then array['pos', 'kitchen', 'orders', 'menu', 'inventory', 'stocktake', 'receive_goods', 'attendance', 'advance']
    when 'cashier' then array['pos', 'orders', 'stocktake', 'attendance', 'advance']
    when 'kitchen' then array['kitchen', 'attendance']
    when 'inventory' then array['inventory', 'stocktake', 'receive_goods', 'attendance']
    else array[]::text[] end
$$;

-- owner: everything. Others: an explicit "off" wins, then an unexpired "on", then the role default.
create or replace function public.has_perm(p text)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select case
    when r is null then false
    when r = 'owner' then true
    when exists (select 1 from public.user_permissions up where up.user_id = auth.uid() and up.permission = p and up.effect = 'deny') then false
    when exists (select 1 from public.user_permissions up where up.user_id = auth.uid() and up.permission = p and up.effect = 'grant'
                 and (up.expires_at is null or up.expires_at > now())) then true
    else p = any(public.role_defaults(r)) end
  from (select public.current_user_role() as r) x
$$;

create or replace function public.my_permissions()
returns text[]
language sql
stable
security definer
set search_path = public
as $$
  select coalesce(array_agg(p), '{}')
  from unnest(public.role_defaults('owner')) p
  where public.has_perm(p)
$$;

-- ---------------------------------------------------------------------
-- Enforcement in functions
-- ---------------------------------------------------------------------
do $$
declare
  def text;
begin
  -- selling
  def := pg_get_functiondef('public.place_order(jsonb)'::regprocedure);
  def := replace(def, $r$  v_role := public.require_role('owner', 'manager', 'cashier');$r$,
    $r$  v_role := public.require_role('owner', 'manager', 'cashier', 'kitchen', 'inventory');
  perform public.require_perm('pos');$r$);
  if position($q$require_perm('pos')$q$ in def) = 0 then raise exception 'place_order patch failed'; end if;
  execute def;

  def := pg_get_functiondef('public.add_payment(uuid, jsonb)'::regprocedure);
  def := replace(def, $r$  v_role public.app_role := public.require_role('owner', 'manager', 'cashier');$r$,
    $r$  v_role public.app_role := public.require_role('owner', 'manager', 'cashier', 'kitchen', 'inventory');$r$);
  def := replace(def, $r$  select * into v_order from public.orders where id = p_order_id for update;$r$,
    $r$  if not (public.has_perm('pos') or public.has_perm('orders')) then
    raise exception 'FORBIDDEN' using errcode = '42501';
  end if;
  select * into v_order from public.orders where id = p_order_id for update;$r$);
  execute def;

  -- advances from the drawer
  def := pg_get_functiondef('public.record_advance(uuid, numeric, text)'::regprocedure);
  def := replace(def, $r$  v_role public.app_role := public.require_role('owner', 'manager', 'cashier');$r$,
    $r$  v_role public.app_role := public.require_role('owner', 'manager', 'cashier', 'kitchen', 'inventory');$r$);
  def := replace(def, $r$  if p_amount is null or p_amount <= 0 or p_amount > 100000 then$r$,
    $r$  perform public.require_perm('advance');
  if p_amount is null or p_amount <= 0 or p_amount > 100000 then$r$);
  execute def;

  -- kitchen board / marking served
  def := pg_get_functiondef('public.advance_kitchen_status(uuid, public.kitchen_status)'::regprocedure);
  def := replace(def, $r$  select * into v_order from public.orders where id = p_order_id for update;$r$,
    $r$  if not (public.has_perm('kitchen') or public.has_perm('orders')) then
    raise exception 'FORBIDDEN' using errcode = '42501';
  end if;
  select * into v_order from public.orders where id = p_order_id for update;$r$);
  def := replace(def, $r$public.require_role('owner', 'manager', 'kitchen', 'cashier')$r$, $r$public.require_role('owner', 'manager', 'kitchen', 'cashier', 'inventory')$r$);
  execute def;

  -- goods receipt and purchase receiving
  def := pg_get_functiondef('public.receive_goods(jsonb, uuid, date, text)'::regprocedure);
  def := replace(def, $r$  perform public.require_role('owner', 'manager', 'inventory', 'cashier');$r$,
    $r$  if not (public.has_perm('receive_goods') or public.has_perm('inventory')) then
    raise exception 'FORBIDDEN' using errcode = '42501';
  end if;$r$);
  execute def;
  def := pg_get_functiondef('public.receive_purchase_order(uuid)'::regprocedure);
  def := replace(def, $r$  perform public.require_role('owner', 'manager', 'inventory', 'cashier');$r$,
    $r$  if not (public.has_perm('receive_goods') or public.has_perm('inventory')) then
    raise exception 'FORBIDDEN' using errcode = '42501';
  end if;$r$);
  execute def;

  -- stocktake: counting vs. approving the differences
  def := pg_get_functiondef('public.create_stock_count(text)'::regprocedure);
  def := replace(def, $r$  perform public.require_role('owner', 'manager', 'inventory', 'cashier');$r$, $r$  perform public.require_perm('stocktake');$r$);
  execute def;
  def := pg_get_functiondef('public.apply_stock_count_impl(uuid)'::regprocedure);
  def := replace(def, $r$  perform public.require_role('owner', 'manager', 'inventory');$r$, $r$  perform public.require_perm('stocktake_approve');$r$);
  execute def;
end;
$$;

-- ---------------------------------------------------------------------
-- Enforcement in table access
-- ---------------------------------------------------------------------
-- menu: everyone reads (the cashier sells from it); changing it needs 'menu'
drop policy if exists categories_write on public.categories;
create policy categories_write on public.categories for all to authenticated
  using (public.has_perm('menu')) with check (public.has_perm('menu'));
drop policy if exists menu_items_write on public.menu_items;
create policy menu_items_write on public.menu_items for all to authenticated
  using (public.has_perm('menu')) with check (public.has_perm('menu'));
drop policy if exists menu_item_options_write on public.menu_item_options;
create policy menu_item_options_write on public.menu_item_options for all to authenticated
  using (public.has_perm('menu')) with check (public.has_perm('menu'));

